dict_a = {'a': 1, 'b': 2}
dict_b = {'b': 3, 'c': 4}

# Python 3.9+ merge operator
merged = dict_a | dict_b
print(merged)  # {'a': 1, 'b': 3, 'c': 4}

# In-place merge
dict_a |= dict_b
print(dict_a)  # {'a': 1, 'b': 3, 'c': 4}

# Python 3.5+ unpacking (creates new dict)
merged2 = {**dict_a, **dict_b}

# Classic .update() method
base = {'x': 10}
base.update({'y': 20})
print(base)  # {'x': 10, 'y': 20}
